// The invariants of a CW complex: homology, Betti numbers, cohomology and the fundamental
// group.
//
// Homology is the cellular homology of the complex's chain complex (morphe/algebra), which is
// the singular homology of the space (Hatcher 2002, Theorem 2.35), with generators as
// cellular cycles.
//
// The fundamental group (Hatcher, Proposition 1.26 and Corollary 1.28): let T be a spanning
// tree of the 1-skeleton's component containing the base vertex. Then π_1(X, base) is
// generated by the edges outside T, an edge e standing for the loop that runs through T to
// its tail, along e, and back through T from its head; each 2-cell of that component gives
// the relator read from its attaching word with the edges of T deleted. Only the 2-skeleton
// matters: cells of higher dimension do not change π_1.

#pragma once

#include <cstddef>
#include <string>
#include <vector>

#include <morphe/algebra/chain_complex.hpp>
#include <morphe/algebra/presentation.hpp>

#include "cw_complex.hpp"

namespace morphe::topology {

inline std::vector<algebra::HomologyGroup> homology(const CWComplex& X, bool generators = true) { return algebra::homology(X.chain_complex(), generators); }
inline std::vector<std::size_t> betti(const CWComplex& X, std::uint64_t p = 0) { return algebra::betti(X.chain_complex(), p); }

struct FundamentalGroup {
  std::size_t base = 0;
  algebra::Presentation presentation;       // on the edges outside the spanning tree
  std::vector<std::size_t> generator_edges;  // the edge of each generator
  std::vector<Path> loops;                   // the closed path at base of each generator
  algebra::Simplified simplified;            // after Tietze simplification
  std::vector<Path> simplified_loops;        // the loops of the kept generators
  algebra::AbelianGroup abelianisation;
};

inline FundamentalGroup fundamental_group(const CWComplex& X, std::size_t base = 0) {
  FundamentalGroup G;
  G.base = base;
  if (X.vertices == 0) return G;
  const auto skeleton = X.one_skeleton();
  const auto T = combinatorics::spanning_forest(skeleton, base);
  const std::size_t comp = T.component[base];
  std::vector<int> letter(X.edges.size(), 0);
  for (std::size_t e = 0; e < X.edges.size(); e++) {
    if (T.in_tree[e] || T.component[X.edges[e][0]] != comp) continue;
    G.generator_edges.push_back(e);
    letter[e] = static_cast<int>(G.generator_edges.size());
    G.presentation.names.push_back(X.edge_name(e));
    // base -> tail through T, e, head -> base through T.
    Path loop = T.path(base, X.edges[e][0], skeleton);
    loop.push_back({e, 1});
    const Path back = T.path(X.edges[e][1], base, skeleton);
    loop.insert(loop.end(), back.begin(), back.end());
    G.loops.push_back(loop);
  }
  G.presentation.generators = G.generator_edges.size();
  for (const auto& f : X.faces) {
    if (T.component[f.base] != comp) continue;
    algebra::Word r;
    for (const auto& s : f.boundary)
      if (letter[s.edge]) r.push_back(s.sign * letter[s.edge]);
    G.presentation.relators.push_back(r);
  }
  G.simplified = algebra::simplify(G.presentation);
  for (std::size_t k : G.simplified.kept) G.simplified_loops.push_back(G.loops[k]);
  G.abelianisation = algebra::abelianisation(G.presentation);
  return G;
}

}  // namespace morphe::topology
